#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-04

# =============================================================================
# Eval Result Staleness Detector
# =============================================================================
# A quality result describes the SKILL.md that existed when it ran. Nothing
# noticed when that stopped being true, so results silently aged into fiction:
# measured 2026-08-04, 39 of 39 quality results predated the SKILL.md they
# graded, including visualize-plan (result 2026-03-14, skill modified since).
#
# Concretely: visualize-plan.quality.json reports 66% PARTIAL for a version of
# the skill that no longer exists. Read today it understates or overstates the
# skill, and there is no way to tell which without re-running.
#
# WHAT THIS IS NOT: a CI gate. tests/evals/results/ is gitignored
# (.gitignore:195) and `git ls-files tests/evals/results/skills/` returns 0, so
# in CI there is nothing to scan and this passes trivially. It is a LOCAL
# signal for the person about to trust a number on their own machine. Saying so
# here rather than letting it look like coverage it does not provide.
#
# Exit 0 always unless EVAL_STALENESS_ENFORCE=1, because the whole 39-file
# backlog is stale today and a red gate on arrival gets switched off.
# =============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
cd "$REPO_ROOT"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; YELLOW=$'\033[1;33m'
BLUE=$'\033[0;34m'; BOLD=$'\033[1m'; NC=$'\033[0m'

ENFORCE="${EVAL_STALENESS_ENFORCE:-0}"
RESULTS_DIR="tests/evals/results/skills"

echo "${BLUE}${BOLD}Eval result staleness (result older than the skill it grades)${NC}"

if [[ ! -d "$RESULTS_DIR" ]]; then
    echo "  ${GREEN}✓${NC} no results directory — nothing to check"
    echo "    (expected in CI: results are gitignored and never committed)"
    exit 0
fi

# ONE python pass over the whole set. Portable mtime comparison without
# guessing which stat(1) flavour this machine has, and without spawning three
# interpreters per result file.
scan="$(python3 - "$RESULTS_DIR" <<'PY'
import glob, os, sys
from datetime import datetime, timezone

results_dir = sys.argv[1]
fresh = stale = unmatched = 0
lines = []

def day(path):
    return datetime.fromtimestamp(os.path.getmtime(path), timezone.utc).strftime("%Y-%m-%d")

for r in sorted(glob.glob(os.path.join(results_dir, "*.quality.json"))):
    skill = os.path.basename(r)[: -len(".quality.json")]
    skill_md = os.path.join("src", "skills", skill, "SKILL.md")
    if not os.path.exists(skill_md):
        unmatched += 1
        continue
    if os.path.getmtime(r) < os.path.getmtime(skill_md):
        stale += 1
        lines.append("STALE\t%s\t%s\t%s" % (skill, day(r), day(skill_md)))
    else:
        fresh += 1

print("COUNTS\t%d\t%d\t%d" % (fresh, stale, unmatched))
for line in lines:
    print(line)
PY
)"

# grep exit 1 here would mean the scan emitted no COUNTS line, i.e. the check
# silently did not run. That is a hard failure, not something to shrug off.
counts_line=""
grep_rc=0
counts_line="$(printf '%s\n' "$scan" | grep '^COUNTS')" || grep_rc=$?
if (( grep_rc != 0 )) || [[ -z "$counts_line" ]]; then
    echo "  ${RED}✗ staleness scan produced no COUNTS line — the check did not run${NC}" >&2
    exit 1
fi
IFS=$'\t' read -r _ fresh stale unmatched <<< "$counts_line"

if (( fresh + stale + unmatched == 0 )); then
    echo "  ${GREEN}✓${NC} no quality results present — nothing to check"
    exit 0
fi

stale_list="$(printf '%s\n' "$scan" | awk -F'\t' '$1=="STALE" {printf "      %s  (result %s, skill %s)\n", $2, $3, $4}')"

echo ""
echo "  ${GREEN}●${NC} current:   ${fresh}"
echo "  ${YELLOW}●${NC} stale:     ${stale}   (skill changed after the result was written)"
echo "  ${BLUE}●${NC} no skill:  ${unmatched}  (result with no matching src/skills/<name>/SKILL.md)"
echo ""

if (( stale > 0 )); then
    echo "${YELLOW}Stale results — these describe a version of the skill that no longer exists:${NC}"
    printf '%s' "$stale_list" | head -20
    if (( stale > 20 )); then
        echo "      … and $((stale - 20)) more"
    fi
    echo ""
    echo "  Re-run one with: ${BOLD}npm run eval:quality -- <skill>${NC}"
    echo "  Set ${BOLD}EVAL_STALENESS_ENFORCE=1${NC} to fail on stale results."
    echo ""
fi

if (( stale > 0 && ENFORCE == 1 )); then
    echo "${RED}✗ ${stale} stale eval result(s) with enforcement on.${NC}"
    exit 1
fi

if (( stale == 0 )); then
    echo "${GREEN}✓ All eval results are at least as new as the skills they grade${NC}"
else
    echo "${YELLOW}(Advisory — not failing.)${NC}"
fi
exit 0
